#!/usr/bin/env bash
# Scene 6, Reusable: the same release and the same commands serve a second application: Alice creates a
# registry with the closed flag of the open-datum application (create --closed), registers a name with a
# payload (insert --fold), reads it back, is refused when she asks to update the payload (the closed
# application is written once; the refusal builds nothing, signs nothing and writes nothing), and
# terminates the name (terminate --fold). Every write signs from her vault in one command. Shapes follow
# the repository's closed-datum journey.
# shellcheck disable=SC2086  # the journal paths are globs over the run's directories the shell must expand
# shellcheck disable=SC2016  # the typed commands are shown verbatim on screen and evaluated by the tour helper
set -euo pipefail
export DEMO_TOTAL=6
# shellcheck disable=SC1091 # resolved from this script's own directory at runtime
. "$(dirname "$0")/lib.sh"
JC='state-closed/net-42/*/wallets/*/journal.jsonl'
play_cd $'Alice is back. The same release, the same commands, serve a second application:\nshe creates a registry with the closed flag of the open-datum application.' alice
play -t -p 6 $'One flag changes the application the registry runs: with --closed, its application refuses\nevery update. The commands, and her vault, are the ones she used before.' \
  'open-datum create --closed --state-dir state-closed $BLUEPRINT $NODE $VAULT 3< ../vault-pass/alice > closed-create.json'
# WORKAROUND: the closed registry's token is exported between frames -> a user pastes it from the create receipt into each later command.
printf 'export TOKEN="--state-token %s"\n' "$(jq -r .stateToken closed-create.json)" >"$RUN/token2.env"
# shellcheck disable=SC1091 # generated by this scene into the run scratch directory
. "$RUN/token2.env"
play -p 8 $'On chain: a second registry exists. The receipt names the application that runs it:\nopen_datum.closed_datum, the closed variant, on the same mint.' \
  'jq "{application, outcome, stateToken, root}" closed-create.json | short'
play -p 10 $'On disk: a second state directory, state-closed, holding what create wrote there: the journal\nof the bundle\'s transactions, and the bundle with its transactions, kept for recovery.' \
  'find state-closed -type f | sort | short'
play -t -p 4 $'She registers checkpoint with her payload, booking and folding in one command, as before.\nThe name points at what her application decides: here, her own identifier.' \
  'open-datum insert --key checkpoint --payload payload.json --payload-schema detailed --state-dir state-closed $TOKEN $BLUEPRINT $NODE $VAULT --fold 3< ../vault-pass/alice > closed-insert.json'
play -p 12 $'On chain: checkpoint is active in the closed registry, settled by the fold in the same command.' \
  'jq "{outcome, keyText, settled: [.settled[] | {edge, owner}], root}" closed-insert.json | short'
play -p 8 $'On disk, in state-closed: the journal grew by the two transactions (book, then fold), and the\nbundle and its transactions are kept in submissions/ for recovery.' \
  "tail -n 4 $JC | jq -c \"{journalStep, journalEvent, tx: (.journalTxId[0:8])}\""
play -t -p 3 "She reads checkpoint back from the chain: a read; it writes nothing on disk." \
  'open-datum inspect --key checkpoint --state-dir state-closed $TOKEN $BLUEPRINT $NODE > closed-inspect.json'
play -p 12 $'On chain: checkpoint is active, and the payload she set at registration is what the name\npoints to. In the closed application a payload is written once.' \
  'jq "{leaf, keyText, payload: .applicationOutput.payload}" closed-inspect.json | short'
play -p 4 "A different payload she would point the name at instead." \
  'jq -n "{constructor:3, fields:[{bytes:\"626f62\"},{int:123456789012345678901234567890}]}" > payload-update.json'
play -f -p 5 $'She asks to update the payload. The closed application refuses before anything is built:\nno bundle, nothing is signed or sent, nothing changes on chain.' \
  'open-datum update --key checkpoint --payload payload-update.json --payload-schema detailed --state-dir state-closed $TOKEN $BLUEPRINT $NODE $VAULT 3< ../vault-pass/alice > closed-update.json'
play -p 10 "The refusal, from the receipt: this registry is closed, and a payload is written once." \
  'jq "{outcome, reason}" closed-update.json | short'
play -p 8 $'On disk: nothing in state-closed is newer than the insert. The refusal wrote no journal line\nand kept no bundle or transaction.' \
  'find state-closed -type f -newer closed-insert.json | grep . || echo "nothing new"'
test -z "$(find state-closed -type f -newer closed-insert.json)"
play -t -p 7 $'Only terminate remains. She terminates checkpoint, booking and folding in one command:\nthe fold burns the token and records the name terminal.' \
  'open-datum terminate --key checkpoint --state-dir state-closed $TOKEN $BLUEPRINT $NODE $VAULT --fold 3< ../vault-pass/alice > closed-terminate.json'
play -p 12 $'On chain: checkpoint is terminal, and the deposit is released from its application output.\nThe same mint served two applications, with no change to its contract.' \
  'jq "{outcome, keyText, settled: [.settled[] | {edge, deposit: .settlement.deposit}]}" closed-terminate.json | short'
play -t -p 3 "She reads checkpoint once more: terminal, with no live output holding its token." \
  'open-datum inspect --key checkpoint --state-dir state-closed $TOKEN $BLUEPRINT $NODE > closed-terminal.json'
play -p 8 $'On chain: terminal. Written once, ended once: that is the whole life of a name in the\nclosed application.' \
  'jq "{leaf, keyText, applicationOutput}" closed-terminal.json'
finish
